def transform(g):
 R,C=len(g),len(g[0]); counts={v:sum(row.count(v) for row in g) for v in set(sum(g,[]))}; bg=max(counts,key=counts.get)
 best=(0,None)
 for color in counts:
  if color==bg: continue
  for r in range(R):
   n=0
   for c in range(C): n=n+1 if g[r][c]==color else 0; best=max(best,(n,color))
  for c in range(C):
   n=0
   for r in range(R): n=n+1 if g[r][c]==color else 0; best=max(best,(n,color))
 marker=best[1]; marks=[(r,c) for r in range(R) for c in range(C) if g[r][c]==marker]; seen=set(); comps=[]
 for r in range(R):
  for c in range(C):
   if g[r][c] in (bg,marker) or (r,c) in seen: continue
   col=g[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    a,b=q.pop(); comp.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<R and 0<=y<C and (x,y) not in seen and g[x][y]==col: seen.add((x,y));q.append((x,y))
   d=min(abs(a-x)+abs(b-y) for a,b in comp for x,y in marks); comps.append((d,comp))
 out=[row[:] for row in g]
 for r,c in min(comps,key=lambda z:z[0])[1]: out[r][c]=marker
 return out
